draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;
ctx.textAlign = "center";

var colY = [H * 0.30, H * 0.72];
var colX = [W * 0.26, W * 0.74];

function arrowTo(ax, ay, bx, by) {
  ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(bx, by); ctx.stroke();
  var a = Math.atan2(by - ay, bx - ax);
  ctx.beginPath();
  ctx.moveTo(bx, by);
  ctx.lineTo(bx - 7 * Math.cos(a - 0.4), by - 7 * Math.sin(a - 0.4));
  ctx.lineTo(bx - 7 * Math.cos(a + 0.4), by - 7 * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}

function resistor(cx, cy, w) {
  ctx.strokeStyle = C.figure;
  ctx.beginPath();
  ctx.moveTo(cx - w, cy);
  var k;
  for (k = 0; k < 6; k++) ctx.lineTo(cx - w + (w * 2 / 6) * (k + 0.5), cy + (k % 2 === 0 ? -8 : 8));
  ctx.lineTo(cx + w, cy);
  ctx.stroke();
}

function battery(cx, cy, plusLeft) {
  ctx.strokeStyle = C.ink;
  var s = plusLeft ? -1 : 1;
  ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(cx + 5 * s, cy - 10); ctx.lineTo(cx + 5 * s, cy + 10); ctx.stroke();
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(cx - 5 * s, cy - 6); ctx.lineTo(cx - 5 * s, cy + 6); ctx.stroke();
}

var i, j;
for (j = 0; j < 2; j++) {
  for (i = 0; i < 2; i++) {
    var cx = colX[i], cy = colY[j], w = Math.min(W * 0.16, 54);
    // lead wires
    ctx.strokeStyle = C.rule; ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(cx - w - 26, cy); ctx.lineTo(cx - w, cy);
    ctx.moveTo(cx + w, cy); ctx.lineTo(cx + w + 26, cy);
    ctx.stroke();

    if (j === 0) resistor(cx, cy, w); else battery(cx, cy, i === 1);

    // walking arrow, always left to right
    ctx.strokeStyle = C.accent; ctx.fillStyle = C.accent; ctx.lineWidth = 1.5;
    arrowTo(cx - w - 24, cy - 26, cx - w + 6, cy - 26);
    ctx.fillText("walk", cx - w - 9, cy - 32);
  }
}

// current arrows on the resistor row
ctx.strokeStyle = C.ink; ctx.fillStyle = C.ink; ctx.lineWidth = 1.5;
arrowTo(colX[0] - 10, colY[0] + 26, colX[0] + 24, colY[0] + 26);
arrowTo(colX[1] + 24, colY[0] + 26, colX[1] - 10, colY[0] + 26);
ctx.fillText("I", colX[0] + 7, colY[0] + 42);
ctx.fillText("I", colX[1] + 7, colY[0] + 42);

// labels
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.ink;
ctx.fillText("resistor, walking with the current", colX[0], colY[0] - 46);
ctx.fillText("term is  -IR", colX[0], colY[0] + 62);
ctx.fillText("resistor, walking against it", colX[1], colY[0] - 46);
ctx.fillText("term is  +IR", colX[1], colY[0] + 62);
ctx.fillText("battery, minus plate first", colX[0], colY[1] - 46);
ctx.fillText("term is  +E", colX[0], colY[1] + 40);
ctx.fillText("battery, plus plate first", colX[1], colY[1] - 46);
ctx.fillText("term is  -E", colX[1], colY[1] + 40);

// plate signs
ctx.fillStyle = C.figure;
ctx.fillText("-", colX[0] - 14, colY[1] - 16);
ctx.fillText("+", colX[0] + 16, colY[1] - 16);
ctx.fillText("+", colX[1] - 14, colY[1] - 16);
ctx.fillText("-", colX[1] + 16, colY[1] - 16);

out.note = "add the four kinds of term round a loop and set the total to zero";
